#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
	// your code goes here
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    
    int T;
    cin >> T;
    
    while(T--){
        int n; 
        cin >> n;
        
        int m=3*n;
        vector<ll> v(m);
        
        for(ll &x:v){
            cin>>x;
        }
        
        sort(v.rbegin(), v.rend());
        
        vector<ll> pref(m+1, 0);
        
        for(int i=0; i<m; ++i){
            pref[i+1] = pref[i] + v[i];
            
        }
        
        auto value = [&](int a, int b) -> ll{
            int j = a+2*b;
            int k = 3*n-2*a-b;
            
            return 2LL*pref[a]+pref[j]+3LL*pref[k];
        };
        
        ll ans=0;
        int b = n;
        
        for(int a=0; a<=n; ++a){
            b=min(b, n-a);
            
            while(b>0 && value(a, b-1)>= value(a,b)){
                --b;
            }
            
            ans = max(ans, value(a,b));
        }
        
        cout << ans << '\n';
    }
    return 0;
}
